import{_ as n,C as o,o as l,c as h,ai as e,j as a,a as t,G as r}from"./chunks/framework.Ci0kozOl.js";const F=JSON.parse('{"title":"Data Model & Values Format","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/architecture/data-model.md","filePath":"3.0/architecture/data-model.md","lastUpdated":1786019473000}'),d={name:"3.0/architecture/data-model.md"},p={id:"variants-and-inherited-values",tabindex:"-1"};function c(k,s,u,E,g,y){const i=o("Badge");return l(),h("div",null,[s[3]||(s[3]=e(`<h1 id="data-model-values-format" tabindex="-1">Data Model &amp; Values Format <a class="header-anchor" href="#data-model-values-format" aria-label="Permalink to &quot;Data Model &amp; Values Format&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Every catalog in UnoPim is built from a small set of entities — channels, locales, attributes, families, categories, and products — and every product stores its attribute data in a single, well-defined JSON document. Once you understand how these pieces fit together, the rest of the platform becomes much easier to reason about.</p><p>This page is the reference for that structure — the equivalent of a &quot;standard format&quot; specification. You should read it before writing importers, exporters, API clients, or anything else that touches <code>products.values</code>, since every one of those tools produces or consumes the format described here.</p><p>We will start with the core entities, walk through the values document itself, and finish with the more advanced topics: variant inheritance, scope resolution, and completeness.</p><h2 id="core-entities" tabindex="-1">Core Entities <a class="header-anchor" href="#core-entities" aria-label="Permalink to &quot;Core Entities&quot;">​</a></h2><p>A <strong>channel</strong> represents a distribution context — a web store, a print catalog, a marketplace — with its own set of locales and currencies. A <strong>locale</strong> is a language/region pair such as <code>en_US</code> or <code>de_DE</code>, and each locale is enabled per channel.</p><p>An <strong>attribute</strong> is a typed field (<code>text</code>, <code>select</code>, <code>price</code>, <code>image</code>, <code>measurement</code>, and so on) that carries per-channel and per-locale scoping flags. Attributes are organized into <strong>attribute groups</strong>, which control how they are presented, and groups are assembled into an <strong>attribute family</strong> — the schema a product follows, defining which attributes it has and in which groups they appear.</p><p>A <strong>category</strong> is a node in a nested-set tree and may carry custom <strong>category fields</strong>. A <strong>product</strong> is <code>simple</code>, <code>configurable</code>, or (internally) <code>variant_group</code>, and carries the <code>values</code> JSON document described below. An <strong>association type</strong> defines a named product-to-product relationship with optional per-link fields, while a <strong>measurement family</strong> defines the units and conversion rules available to measurement attributes.</p><h2 id="the-product-values-document" tabindex="-1">The Product Values Document <a class="header-anchor" href="#the-product-values-document" aria-label="Permalink to &quot;The Product Values Document&quot;">​</a></h2><p>Every product stores its attribute data in one JSON column, <code>products.values</code>, partitioned by <strong>scope</strong>. Let&#39;s walk through a complete example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;common&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sku&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shirt-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;brand&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;verano&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;locale_specific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;en_US&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Harbour Overshirt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;de_DE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Harbour Überhemd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;channel_specific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ecommerce&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;channel_locale_specific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ecommerce&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;en_US&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;p&gt;…&lt;/p&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;categories&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apparel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shirts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;associations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;related_products&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shirt-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;up_sells&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;cross_sells&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>common</code> bucket holds values that are the same everywhere — here, the <code>sku</code> and <code>brand</code> apply regardless of channel or locale. The <code>locale_specific</code> bucket is keyed by locale, so the product&#39;s <code>name</code> can differ between <code>en_US</code> and <code>de_DE</code> while remaining channel-independent. The <code>channel_specific</code> bucket is keyed by channel: the <code>status</code> value applies to the <code>ecommerce</code> channel in every locale. Finally, <code>channel_locale_specific</code> nests channel and then locale, so the <code>description</code> shown here belongs only to the <code>ecommerce</code> channel in <code>en_US</code>. Alongside the four scope buckets, <code>categories</code> lists the product&#39;s category codes and <code>associations</code> lists linked SKUs.</p><p>Which bucket an attribute writes to follows directly from its two scoping flags:</p><table tabindex="0"><thead><tr><th><code>value_per_channel</code></th><th><code>value_per_locale</code></th><th>Bucket</th></tr></thead><tbody><tr><td>✗</td><td>✗</td><td><code>common</code></td></tr><tr><td>✗</td><td>✓</td><td><code>locale_specific.&lt;locale&gt;</code></td></tr><tr><td>✓</td><td>✗</td><td><code>channel_specific.&lt;channel&gt;</code></td></tr><tr><td>✓</td><td>✓</td><td><code>channel_locale_specific.&lt;channel&gt;.&lt;locale&gt;</code></td></tr></tbody></table><p>The bucket keys are defined once as constants on <code>Webkul\\Product\\Type\\AbstractType</code> — <code>COMMON_VALUES_KEY</code>, <code>LOCALE_VALUES_KEY</code>, <code>CHANNEL_VALUES_KEY</code>, <code>CHANNEL_LOCALE_VALUES_KEY</code>, <code>CATEGORY_VALUES_KEY</code>, and <code>ASSOCIATION_VALUES_KEY</code>. You should always use the constants rather than string literals.</p><h3 id="value-types-worth-knowing" tabindex="-1">Value Types Worth Knowing <a class="header-anchor" href="#value-types-worth-knowing" aria-label="Permalink to &quot;Value Types Worth Knowing&quot;">​</a></h3><p>A few attribute types store their values in shapes you may not expect. Select and multiselect attributes store option <em>codes</em>, not labels. Media attributes store storage paths, while the files themselves live on the configured disk.</p><p>Measurement values are objects rather than plain scalars:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;unit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;180.0000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;family&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Length&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;base_unit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;base_data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.800000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See <a href="./../packages/measurements.html">Measurements</a> for how these are managed.</p><p>The <code>categories</code> key holds category <em>codes</em>, and <code>associations</code> holds SKU lists for the three legacy sections. Rich associations live in the <code>product_associations</code> table — see <a href="./../packages/configurable-associations.html">Configurable Associations</a>.</p>`,22)),a("h2",p,[s[0]||(s[0]=t("Variants and Inherited Values ",-1)),r(i,{type:"tip",text:"3.0"}),s[1]||(s[1]=t()),s[2]||(s[2]=a("a",{class:"header-anchor",href:"#variants-and-inherited-values","aria-label":'Permalink to "Variants and Inherited Values <Badge type="tip" text="3.0" />"'},"​",-1))]),s[4]||(s[4]=e('<p>For products inside a variant structure, <code>products.values</code> holds only the values the node itself <em>authors</em>. When you need the effective values, UnoPim merges the ancestor chain at read time:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$effective </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $product</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolvedValues</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>You should never read a variant child&#39;s raw <code>values</code> column directly — see <a href="./../packages/advanced-variants.html">Advanced Variants</a> for the full inheritance model.</p><h2 id="scope-resolution" tabindex="-1">Scope Resolution <a class="header-anchor" href="#scope-resolution" aria-label="Permalink to &quot;Scope Resolution&quot;">​</a></h2><p>Whenever UnoPim needs to know the current channel and locale, it resolves the context through <code>Webkul\\Core\\CatalogScope</code> in this order:</p><ol><li>Explicit <code>?channel=</code> / <code>?locale=</code> request parameters (validated against <code>^[a-zA-Z0-9_-]+$</code>)</li><li>The admin&#39;s <strong>catalog locale</strong> and <strong>default channel</strong> preferences (per-user, new in 3.0)</li><li>The default channel and its default locale</li></ol><p>Console and queue contexts skip step 2, since there is no authenticated admin in those contexts.</p><h2 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h2><p>Completeness scores each product per channel and locale against the required attributes of its family. For variant trees, each node is scored only against the attributes it owns at its own level. Scores recalculate automatically on save (queued), on demand via <code>unopim:completeness:recalculate</code>, and nightly by the scheduler.</p>',9))])}const q=n(d,[["render",c]]);export{F as __pageData,q as default};
